import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"邮箱管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mailboxes.md","filePath":"guide/mailboxes.md","lastUpdated":1777953542000}`),a={name:`guide/mailboxes.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="邮箱管理" tabindex="-1">邮箱管理 <a class="header-anchor" href="#邮箱管理" aria-label="Permalink to “邮箱管理”">​</a></h1><h2 id="创建与配额" tabindex="-1">创建与配额 <a class="header-anchor" href="#创建与配额" aria-label="Permalink to “创建与配额”">​</a></h2><p>在“管理 → 邮箱管理”选择域名并输入前缀。系统同时检查地址占用、保留前缀、域名是否允许注册、用户等级和套餐邮箱数量上限。</p><p>配额来自多层规则：平台默认值、用户等级、个人订阅、企业订阅以及管理员为用户单独设置的覆盖值。页面“我的套餐”和邮箱存储详情显示当前生效结果。</p><h2 id="基本资料与排序" tabindex="-1">基本资料与排序 <a class="header-anchor" href="#基本资料与排序" aria-label="Permalink to “基本资料与排序”">​</a></h2><p>每个邮箱可以维护显示名称、转发目标等资料。拖动排序后，新的顺序会用于邮箱选择器；第一个可用邮箱通常是登录后的默认邮箱。</p><h2 id="转发与自动回复" tabindex="-1">转发与自动回复 <a class="header-anchor" href="#转发与自动回复" aria-label="Permalink to “转发与自动回复”">​</a></h2><p>转发把新邮件发送到指定外部地址。配置错误可能形成循环，因此不要把两个邮箱互相转发。</p><p>自动回复支持启用状态、正文、开始与结束时间、回复范围以及邮箱级覆盖。系统会尽量跳过邮件列表、自动邮件和疑似循环，并限制同一发件人的重复回复。</p><h2 id="应用专用密码" tabindex="-1">应用专用密码 <a class="header-anchor" href="#应用专用密码" aria-label="Permalink to “应用专用密码”">​</a></h2><p>IMAP、POP3 和 SMTP 客户端使用邮箱地址与应用专用密码认证。创建时为密码填写易识别的名称，例如“iPhone”或“Thunderbird”。密码只在创建时完整显示，应立即保存到密码管理器。</p><p>怀疑泄露时删除对应应用密码，不必修改网页登录密码。不同设备使用不同密码，便于单独撤销。</p><h2 id="邮箱共享" tabindex="-1">邮箱共享 <a class="header-anchor" href="#邮箱共享" aria-label="Permalink to “邮箱共享”">​</a></h2><p>共享通过邀请完成。被邀请人可以接受或拒绝；所有者可以调整授权范围、查看共享活动、撤销单个邀请或一次撤销全部共享。只向可信账号授权，并定期清理不再需要的访问。</p><h2 id="邮箱转让" tabindex="-1">邮箱转让 <a class="header-anchor" href="#邮箱转让" aria-label="Permalink to “邮箱转让”">​</a></h2><p>转让会把邮箱所有权交给另一位用户。请求可接受、拒绝或在完成前取消。转让前应确认目标用户、邮箱内容和后续配额，因为所有权变化会影响管理与删除权限。</p><h2 id="归档与删除" tabindex="-1">归档与删除 <a class="header-anchor" href="#归档与删除" aria-label="Permalink to “归档与删除”">​</a></h2><p>归档邮箱适合暂停使用但保留数据。删除邮箱前先处理转发、共享、客户端密码和重要邮件。企业邮箱还受组织角色和企业套餐限制。</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};